select throws_ok($$select public.save_product_storefront((select v::uuid from sf_results where k='sf'),pg_temp.sf_rev((select v::uuid from sf_results where k='sf')),'Stolen storefront','Description','Contact')$$,'STOREFRONT_NOT_FOUND','cannot edit another storefront');
