select pg_temp.sf_admin();
select public.set_storefront_editorial((select v::uuid from sf_results where k='sf'),pg_temp.sf_rev((select v::uuid from sf_results where k='sf')),'draft','Synthetic moderator allows resubmission');
select pg_temp.set_test_user('74000000-0000-0000-0000-000000000001',true);
