create function pg_temp.fail_storefront_grant() returns trigger language plpgsql as $$begin raise exception 'SYNTHETIC_STOREFRONT_GRANT_FAILURE';end$$;
create trigger storefront_fault before update on public.visibility_entitlements for each row execute function pg_temp.fail_storefront_grant();
set local role authenticated;
select throws_ok($$select public.confirm_commercial_order((select v::uuid from sf_results where k='fault'),true)$$,'SYNTHETIC_STOREFRONT_GRANT_FAILURE','fault after debit cannot partially publish storefront');
reset role;
drop trigger storefront_fault on public.visibility_entitlements;
select is((select cash_balance from public.wallets where user_id='74000000-0000-0000-0000-000000000001'),137,'grant fault preserves wallet');
select is((select count(*)::integer from public.economy_transactions where reference_id=(select v from sf_results where k='fault')),0,'grant fault preserves ledger');
select is((select status from public.commercial_orders where id=(select v::uuid from sf_results where k='fault')),'quoted','grant fault leaves quote unfulfilled');
select is((select to_jsonb(e) from public.visibility_entitlements e where resource_id=(select v::uuid from sf_results where k='sf')),(select v::jsonb from sf_results where k='right_before'),'grant fault preserves right exactly');
select pg_temp.sf_admin();
select public.admin_reverse_commercial_order((select v::uuid from sf_results where k='renew'),'74700000-0000-0000-0000-000000000001','Synthetic storefront refund after validation',true);
select public.admin_reverse_commercial_order((select v::uuid from sf_results where k='renew'),'74700000-0000-0000-0000-000000000001','Synthetic storefront refund after validation',true);
select is((select cash_balance from public.wallets where user_id='74000000-0000-0000-0000-000000000001'),151,'concrete storefront reversal credits once');
select is((select count(*)::integer from public.economy_transactions where natural_key='commercial_refund:'||(select v from sf_results where k='renew')),1,'concrete storefront refund has one ledger entry');
select ok(not private.commercial_resource_visible((select v::uuid from sf_results where k='sf')),'reversal removes public visibility immediately');
select ok(exists(select 1 from public.partner_products where id=(select v::uuid from sf_results where k='product')),'reversal preserves product data');
select pg_temp.set_test_user('74000000-0000-0000-0000-000000000001',true);
set local role authenticated;
insert into sf_results values('sf2',public.create_product_storefront('Second synthetic store',gen_random_uuid())::text);
select throws_ok($$select public.save_storefront_product((select v::uuid from sf_results where k='sf2'),pg_temp.sf_rev((select v::uuid from sf_results where k='sf2')),(select v::uuid from sf_results where k='product'),'{}')$$,'PRODUCT_NOT_FOUND','product cannot move between storefronts');
select throws_ok($$select public.create_product_storefront('Excess storefront',gen_random_uuid())$$,'STOREFRONT_LIMIT','storefront limits enforced by owner lock');
select throws_ok($$select public.save_storefront_product((select v::uuid from sf_results where k='sf2'),pg_temp.sf_rev((select v::uuid from sf_results where k='sf2')),null,'{"mediaId":"74200000-0000-0000-0000-000000000001"}')$$,'INVALID_STOREFRONT_MEDIA','media cannot cross storefronts even for the same owner');
select is(public.discard_unused_storefront_media('74200000-0000-0000-0000-000000000001'),null::text,'referenced media cannot be discarded');
select public.save_storefront_product((select v::uuid from sf_results where k='sf2'),pg_temp.sf_rev((select v::uuid from sf_results where k='sf2')),null,'{}');
select public.save_storefront_product((select v::uuid from sf_results where k='sf2'),pg_temp.sf_rev((select v::uuid from sf_results where k='sf2')),null,'{}');
select public.save_storefront_product((select v::uuid from sf_results where k='sf2'),pg_temp.sf_rev((select v::uuid from sf_results where k='sf2')),null,'{}');
select throws_ok($$select public.save_storefront_product((select v::uuid from sf_results where k='sf2'),pg_temp.sf_rev((select v::uuid from sf_results where k='sf2')),null,'{}')$$,'PRODUCT_LIMIT','product limits are enforced in PostgreSQL');
insert into sf_results values('cleanup_media',public.allocate_storefront_media((select v::uuid from sf_results where k='sf2'))->>'id');
select ok(public.discard_unused_storefront_media((select v::uuid from sf_results where k='cleanup_media')) is not null,'unused media cleanup claims a server-owned path');
select throws_ok($$select public.save_product_storefront((select v::uuid from sf_results where k='sf2'),pg_temp.sf_rev((select v::uuid from sf_results where k='sf2')),'No pending logo','Description for cleanup test','Contact',(select v::uuid from sf_results where k='cleanup_media'))$$,'INVALID_STOREFRONT_MEDIA','pending cleanup media cannot be attached concurrently');
reset role;
select is((select state from public.storefront_media where id=(select v::uuid from sf_results where k='cleanup_media')),'deleting','storage failure can retain a tracked retryable cleanup row');
reset role;
update public.users set account_status='disabled' where id='74000000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$select public.list_managed_storefronts()$$,'42501','APP_ACCESS_DENIED','blocked account cannot manage');
select is(public.authorize_storefront_media('74200000-0000-0000-0000-000000000001'),null::text,'blocked owner cannot read private media');
reset role;
update public.users set account_status='active' where id='74000000-0000-0000-0000-000000000001';
-- Account removal nulls both FK owners without destroying financial/editorial history.
select pg_temp.set_test_user('74000000-0000-0000-0000-000000000002',true);
insert into sf_results values('deleted_owner_store',public.create_product_storefront('Store of removed owner',gen_random_uuid())::text);
update private.commercial_resources set moderation_state='approved',approved_revision=content_revision where id=(select v::uuid from sf_results where k='deleted_owner_store');
select lives_ok($$delete from public.users where id='74000000-0000-0000-0000-000000000002'$$,'owner removal preserves referential integrity');
select ok(exists(select 1 from public.product_storefronts where id=(select v::uuid from sf_results where k='deleted_owner_store') and owner_user_id is null),'owner removal preserves storefront data without assigning it to someone else');
select pg_temp.set_test_user('74000000-0000-0000-0000-000000000001',true);
select pg_temp.revoke_test_session('74000000-0000-0000-0000-000000000001');
set local role authenticated;
select throws_ok($$select public.list_managed_storefronts()$$,'42501','APP_ACCESS_DENIED','revoked session cannot manage');
reset role;
select ok(not has_function_privilege('authenticated','private.touch_storefront(uuid)','execute'),'private approval synchronization not exposed');
select ok(not has_table_privilege('authenticated','public.storefront_media','update'),'no direct media attestation or ownership changes');
select ok(not exists(select 1 from storage.buckets where id='storefront-media' and public),'media bucket is private');
select * from finish();
rollback;
